import csv
rows=[]; bad=0
for (L,r),(laps,foto) in sorted(D.items(), key=lambda k:(-k[0][0],k[0][1])):
    prev=0
    for v,tv,ta in laps:
        d=round(ta-prev,2)
        if abs(d-tv)>0.011: print("INCONSISTENTE",L,r,v,tv,ta,d); bad+=1
        prev=ta
        rows.append(dict(longitud_m=L/100,repeticion=r,vuelta=v,t_vuelta_s=f"{tv:.2f}",t_acumulado_s=f"{ta:.2f}",amplitud_grados=9,masa_g=13,fotos=foto))
with open("datos/2026-10-01_pendulo_crudo.csv","w",newline="") as f:
    w=csv.DictWriter(f,fieldnames=list(rows[0])); w.writeheader(); w.writerows(rows)
print("filas",len(rows),"inconsistencias",bad)
